from rdkit import Chem
from rdkit.Chem import rdMolDescriptors
import numpy as np
m=Chem.MolFromMolFile('answer.mol',removeHs=False)
print('Formula',rdMolDescriptors.CalcMolFormula(m),'atoms',m.GetNumAtoms())
old={a.GetIdx():a.GetProp('_CIPCode') for a in m.GetAtoms() if a.HasProp('_CIPCode')}
lines=open('optimized.xyz').read().splitlines(); xyz=np.array([[float(x) for x in l.split()[1:]] for l in lines[2:2+m.GetNumAtoms()]])
for i,v in enumerate(xyz): m.GetConformer().SetAtomPosition(i,v)
Chem.AssignStereochemistryFrom3D(m,replaceExistingTags=True)
new={a.GetIdx():a.GetProp('_CIPCode') for a in m.GetAtoms() if a.HasProp('_CIPCode')}
print('Stereo before',old,'after',new)
assert old==new
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(xyz[i]-xyz[j]);
 if d>1.75: print('long bond',i,j,d)
Chem.MolToXYZFile(m,'answer.xyz')
print('answer.xyz exists; atom count:',len(xyz))
PY

